import { performance } from "node:perf_hooks";
const PROBE_INTERVAL_MS = 100;
/** How far back a hosted reply looks for the worst lag. */
export const HOSTED_EVENT_LOOP_WINDOW_MS = 60_000;
/** Lag under this is timer noise and is not kept. */
const MIN_RECORDED_LAG_MS = 20;
/**
 * The worst event-loop lag this process saw lately, reported on every hosted
 * reply. A status poll that reaches a blocked loop is answered late or not at
 * all, and the host gives up after a few such polls. The window keeps a stall
 * the host abandoned visible on the next poll that does get an answer.
 */
export class EventLoopLagWindow {
    constructor(now = () => performance.now()) {
        this.now = now;
        this.lags = [];
        this.lastTickAtMs = now();
    }
    /** Start the probe timer. It never keeps the process alive. */
    start() {
        if (this.timer !== undefined) {
            return;
        }
        this.lastTickAtMs = this.now();
        this.timer = setInterval(() => this.tick(), PROBE_INTERVAL_MS);
        this.timer.unref();
    }
    tick() {
        const now = this.now();
        const lagMs = now - this.lastTickAtMs - PROBE_INTERVAL_MS;
        this.lastTickAtMs = now;
        if (lagMs >= MIN_RECORDED_LAG_MS) {
            this.lags.push({ atMs: now, lagMs });
        }
    }
    /**
     * Forget earlier lag. A parked guest is frozen between deliveries, and its
     * first tick after the thaw measures the whole freeze.
     */
    clear() {
        this.lags = [];
        this.lastTickAtMs = this.now();
    }
    /** Worst lag in the window, in ms, counting a tick that is overdue right now. */
    worstMs() {
        const now = this.now();
        this.lags = this.lags.filter((lag) => now - lag.atMs <= HOSTED_EVENT_LOOP_WINDOW_MS);
        let worst = this.timer === undefined ? 0 : Math.max(0, now - this.lastTickAtMs - PROBE_INTERVAL_MS);
        for (const lag of this.lags) {
            worst = Math.max(worst, lag.lagMs);
        }
        return worst;
    }
}
export const hostedEventLoopLag = new EventLoopLagWindow();
